<script setup lang="ts">
import { ref } from 'vue';
import { Plus, Search } from '@lucide/vue';
import { roles, roleLabels } from '@assetflow/shared';
import { useCollection } from '../composables/data';
import { useAuth } from '../stores/auth';
import { api } from '../api/client';
import { type User, dateLabel } from '../types';
import AsyncState from '../components/AsyncState.vue';
import Pagination from '../components/Pagination.vue';
import FormDialog from '../components/FormDialog.vue';
const { data, loading, error, page, filters, reload } = useCollection<User>('/users'), auth = useAuth(), dialog = ref<InstanceType<typeof FormDialog>>(), success = ref('');
const options = roles.map(role => ({ value: role, label: roleLabels[role] }));
function create() { void dialog.value?.open({ title: '建立使用者', description: '請透過可信管道交付初始密碼。本版本不提供忘記密碼或寄信功能。', fields: [{ key: 'name', label: '姓名', required: true }, { key: 'email', label: '電子郵件', type: 'email', required: true }, { key: 'role', label: '角色', type: 'select', required: true, options }, { key: 'password', label: '初始密碼', type: 'password', required: true, minLength: 12, hint: '至少 12 個字元。' }], initial: { role: 'VIEWER' }, submitLabel: '建立使用者', onSubmit: async v => { await api('/users', { method: 'POST', body: v }); success.value = '使用者已建立。'; await reload(); } }); }
function edit(u: User) { void dialog.value?.open({ title: '變更使用者權限', description: `${u.name} · 儲存後會撤銷此使用者所有 Session，必須重新登入。系統會保留至少一位啟用管理員。`, fields: [{ key: 'role', label: '角色', type: 'select', required: true, options }, { key: 'active', label: '帳號狀態', type: 'select', required: true, options: [{ value: 'true', label: '啟用' }, { value: 'false', label: '停用' }] }], initial: { role: u.role, active: String(u.active) }, submitLabel: '確認變更', onSubmit: async v => { await api(`/users/${u.id}`, { method: 'PATCH', body: { role: v.role, active: v.active === 'true' } }); if (u.id === auth.user?.id) { auth.clear(); window.dispatchEvent(new Event('session-expired')); return; } success.value = '權限已更新，該帳號所有 Session 已撤銷。'; await reload(); } }); }
</script>
<template><div class="page-heading"><div><span class="eyebrow">ACCESS & PERMISSIONS</span><h1>使用者管理<span class="heading-dot">.</span></h1><p>以適當的角色權限，讓團隊安心協作。</p></div><button class="btn" @click="create"><Plus :size="17" />建立使用者</button></div><p v-if="success" class="notice" role="status">{{ success }}</p><div class="role-cards"><div><strong>ADMIN</strong><p>完整管理資產、員工、流程與帳號權限。</p></div><div><strong>IT_STAFF</strong><p>管理設備與交接流程，無帳號權限管理。</p></div><div><strong>VIEWER</strong><p>唯讀檢視工作空間資產與統計資訊。</p></div></div><section class="panel"><div class="list-toolbar"><div class="search-input"><Search :size="18" /><input v-model="filters.search" type="search" aria-label="搜尋使用者" placeholder="搜尋姓名或電子郵件…"></div></div><AsyncState :loading="loading" :error="error" :empty="!data?.items.length" @retry="reload"><div class="table-scroll"><table><thead><tr><th>使用者</th><th>電子郵件</th><th>角色</th><th>狀態</th><th>建立日期</th><th>操作</th></tr></thead><tbody><tr v-for="u in data?.items" :key="u.id"><td><span class="person-cell"><span class="avatar tiny">{{ u.name.slice(0, 1) }}</span><strong>{{ u.name }}</strong><small v-if="auth.user?.id === u.id" class="subtle-tag">你</small></span></td><td class="muted">{{ u.email }}</td><td><span class="subtle-tag">{{ roleLabels[u.role] }}</span></td><td><span class="badge" :class="u.active ? 'available' : 'retired'"><i />{{ u.active ? '啟用' : '停用' }}</span></td><td>{{ dateLabel(u.createdAt) }}</td><td><button class="btn secondary small" @click="edit(u)">變更權限</button></td></tr></tbody></table></div></AsyncState><Pagination v-if="data" v-model:page="page" :total="data.total" /></section><FormDialog ref="dialog" /></template>
